.newsletter p { color: var(--text-muted); margin-top: 14px; }
.newsletter-form {
  position: relative;
  z-index: 2;
}
.input-row {
  display: flex;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 100px;
  padding: 6px;
  transition: border-color 0.2s;
}
.input-row:focus-within { border-color: var(--accent); }
.input-row input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  padding: 10px 18px;
  font-size: 14px;
  font-family: inherit;
}
.input-row input::placeholder { color: var(--text-dim); }
.input-row button {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  padding: 10px 22px;
  border-radius: 100px;
  font-size: 14px;
  transition: background 0.2s;
}
.input-row button:hover { background: var(--accent-hover); }
.newsletter-perks {
  display: flex; gap: 24px; margin-top: 20px;
  font-size: 12.5px; color: var(--text-muted);
}
.newsletter-perks span { display: inline-flex; align-items: center; gap: 6px; }
.newsletter-perks .check { color: var(--accent); }

/* ---------- Footer ---------- */
.footer {
  margin-top: 80px;
  padding: 64px 0 32px;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand p {
  color: var(--text-muted);
  font-size: 14px;
  margin: 16px 0 24px;
  max-width: 320px;
}
.socials { display: flex; gap: 8px; }
.social {
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: all 0.2s;
}
.social:hover { color: var(--accent); border-color: var(--accent); }
.footer-col h5 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  margin-bottom: 16px;
  font-weight: 600;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col a {
  font-size: 14px;
  color: var(--text-muted);
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  font-size: 12.5px;
  color: var(--text-dim);
  flex-wrap: wrap;
  gap: 16px;
}
.payments { display: flex; gap: 8px; }
.pay-chip {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
}

/* ---------- Toast ---------- */
.toast-wrap {
  position: fixed;
  bottom: 24px; right: 24px;
  z-index: 100;
  display: flex; flex-direction: column; gap: 10px;
}
.toast {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--accent);
  padding: 14px 18px;
  border-radius: 10px;
  font-size: 13.5px;
  min-width: 260px;
  box-shadow: var(--shadow-lg);
  animation: toastIn 0.3s ease;
}
@keyframes toastIn {
  from { transform: translateX(20px); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; }
  .products { grid-template-columns: repeat(2, 1fr); }
  .categories { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal.featured { grid-row: auto; min-height: 280px; grid-column: span 2; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter { grid-template-columns: 1fr; padding: 40px 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .nav { display: none; }
}
@media (max-width: 600px) {
  .container { padding: 0 18px; }
  .products { grid-template-columns: 1fr 1fr; gap: 12px; }
  .categories { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal.featured { grid-column: auto; }
  .hero-stats { gap: 20px; flex-wrap: wrap; }
  .countdown { flex-direction: column; align-items: flex-start; }
  .footer-grid { grid-template-columns: 1fr; }
  .section { padding: 48px 0; }
}

