  padding: 0 32px;
}

/* ---------- Announcement Bar ---------- */
.announce {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 9px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.announce-track {
  display: inline-flex;
  gap: 48px;
  align-items: center;
}
.announce-dot {
  width: 4px; height: 4px; border-radius: 50%;
  background: var(--accent-ink); opacity: 0.45;
}

/* ---------- Header ---------- */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(10,10,12,0.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0;
  gap: 32px;
}
.logo {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-mark {
  width: 28px; height: 28px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  display: grid; place-items: center;
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: 15px;
}
.nav { display: flex; gap: 28px; }
.nav a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  position: relative;
  padding: 6px 0;
  transition: color 0.2s;
}
.nav a:hover { color: var(--text); }
.nav a.active { color: var(--text); }
.nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0; right: 0;
  height: 2px;
  background: var(--accent);
}
.header-actions {
  display: flex; align-items: center; gap: 6px;
}
.icon-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: all 0.2s;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); }
.icon-btn .badge {
  position: absolute;
  top: 5px; right: 5px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 8px;
  display: grid; place-items: center;
  padding: 0 4px;
}

/* ---------- Hero ---------- */
.hero {
  padding: 56px 0 80px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px; right: -200px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(212,255,58,0.08) 0%, transparent 60%);
  pointer-events: none;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: 56px;
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  margin-bottom: 22px;
  padding: 6px 12px;
  border: 1px solid rgba(212,255,58,0.2);
  border-radius: 100px;
  background: rgba(212,255,58,0.04);
}
.hero-eyebrow-pulse {
  width: 6px; height: 6px;
  background: var(--accent);
  border-radius: 50%;
  box-shadow: 0 0 0 4px rgba(212,255,58,0.15);
}
.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(44px, 6vw, 80px);
  line-height: 0.96;
  font-weight: 500;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}
.hero h1 em {
  font-style: italic;
  font-weight: 300;
  color: var(--text-muted);
}
.hero p.lead {
  font-size: 17px;
  color: var(--text-muted);
  max-width: 460px;
  margin-bottom: 36px;
}
.hero-actions {
  display: flex; gap: 12px;
  margin-bottom: 48px;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 22px;
  border-radius: 100px;
  font-size: 14px;
  font-weight: 600;
  transition: all 0.2s;
  border: 1px solid transparent;
}
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); }
.btn-ghost {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--text-dim); }

.hero-stats {
  display: flex;
  gap: 40px;
  padding-top: 32px;
  border-top: 1px solid var(--border);
}
.hero-stat .num {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 500;
  letter-spacing: -0.02em;
  display: block;
}
.hero-stat .lbl {
  font-size: 12px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 4px;
}

.hero-visual {
  position: relative;
  aspect-ratio: 5/6;
  border-radius: 24px;
  overflow: hidden;
  background: var(--grad-1);
  border: 1px solid var(--border);
}
.hero-visual-img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: brightness(0.92) saturate(0.95);
}
.hero-tag {
  position: absolute;
  background: rgba(10,10,12,0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.hero-tag.tl { top: 24px; left: 24px; }
.hero-tag.br { bottom: 24px; right: 24px; }
.hero-tag .swatch {
  width: 36px; height: 36px;
  border-radius: 8px;
}
.hero-tag .name { font-size: 13px; font-weight: 600; }
.hero-tag .price { font-size: 12px; color: var(--text-muted); }
.hero-tag .rating { font-size: 12px; color: var(--gold); }

/* ---------- Section heading ---------- */
.section { padding: 72px 0; }
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: end;
  margin-bottom: 36px;
  gap: 24px;
}
.section-head .eyebrow {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  margin-bottom: 10px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(32px, 4vw, 48px);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.section-head h2 em { font-style: italic; color: var(--text-muted); font-weight: 300; }
.section-head .link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 4px;
  transition: color 0.2s, border-color 0.2s;
}
.section-head .link:hover { color: var(--accent); border-color: var(--accent); }

/* ---------- Categories ---------- */
.categories {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.cat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 22px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  transition: all 0.2s;
  cursor: pointer;
}
.cat:hover {
  border-color: var(--accent);
  background: var(--bg-elev-2);
  transform: translateY(-2px);
}
.cat-icon {
  width: 52px; height: 52px;
  border-radius: 12px;
  background: var(--bg);
  display: grid; place-items: center;
  color: var(--accent);
  border: 1px solid var(--border);
}
.cat-name { font-size: 13px; font-weight: 600; }
.cat-count { font-size: 11px; color: var(--text-dim); }

/* ---------- Featured Products Grid ---------- */
.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: all 0.25s;
  position: relative;
}
.card:hover {
  border-color: var(--border-strong);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.card-media {
  position: relative;
  aspect-ratio: 1/1;
  background: var(--bg-elev-2);
  overflow: hidden;
}
.card-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.5s;
}
.card:hover .card-media img { transform: scale(1.05); }
.card-tags {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; gap: 6px;
  flex-wrap: wrap;
}
.tag {
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 5px 9px;
  border-radius: 100px;
  background: rgba(10,10,12,0.75);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text);
}
.tag.new { background: var(--accent); color: var(--accent-ink); }
.tag.sale { background: var(--danger); color: #fff; }
.tag.limited { background: var(--gold); color: var(--accent-ink); }
.card-fav {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(10,10,12,0.7);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: all 0.2s;
  opacity: 0;
}
.card:hover .card-fav { opacity: 1; }
.card-fav:hover { color: var(--danger); background: rgba(10,10,12,0.9); }
.card-fav.active { color: var(--danger); opacity: 1; }
.card-quick {
  position: absolute;
  left: 12px; right: 12px; bottom: 12px;
  padding: 10px;
  background: rgba(10,10,12,0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-radius: 10px;
  font-size: 12.5px;
  font-weight: 600;
  text-align: center;
  transform: translateY(120%);
  transition: transform 0.3s;
}
.card:hover .card-quick { transform: translateY(0); }
.card-body {
  padding: 16px;
}
.card-cat {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
  margin-bottom: 6px;
}
.card-title {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 10px;
  line-height: 1.3;
}
.card-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.card-price {
  display: flex; align-items: baseline; gap: 8px;
}
.price-now {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.price-was {
  font-size: 13px;
  color: var(--text-dim);
  text-decoration: line-through;
}
.card-rating {
  font-size: 12px;
  color: var(--text-muted);
  display: flex; align-items: center; gap: 4px;
}
.card-rating .star { color: var(--gold); }
.card-swatches {
  display: flex; gap: 5px;
  margin-top: 10px;
}
.swatch-dot {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
}

/* ---------- Deals Strip ---------- */
.deals-section { background: var(--bg-elev); padding: 80px 0; border-block: 1px solid var(--border); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
.deal {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  padding: 32px;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.25s;
  border: 1px solid var(--border);
  background-size: cover;
  background-position: center;
}
.deal:hover { transform: translateY(-3px); }
.deal::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10,10,12,0.2) 0%, rgba(10,10,12,0.85) 100%);
  z-index: 1;
}
.deal > * { position: relative; z-index: 2; }
.deal.featured { grid-row: span 2; min-height: 580px; }
.deal-eyebrow {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
}
.deal h3 {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 500;
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 12px 0 10px;
}
.deal.featured h3 { font-size: 48px; }
.deal p { font-size: 14px; color: var(--text-muted); max-width: 360px; }
.deal-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 600;
  margin-top: 20px;
  align-self: flex-start;
}
.deal-cta::after {
  content: '→';
  transition: transform 0.2s;
}
.deal:hover .deal-cta::after { transform: translateX(4px); }
.deal-discount {
  position: absolute;
  top: 24px; right: 24px;
  z-index: 3;
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 22px;
  padding: 14px 18px;
  border-radius: 100px;
  letter-spacing: -0.02em;
}

/* ---------- Countdown ---------- */
.countdown {
  background: var(--grad-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  margin-top: 32px;
  flex-wrap: wrap;
}
.countdown-text h4 {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.countdown-text p { color: var(--text-muted); font-size: 14px; margin-top: 4px; }
.countdown-timer {
  display: flex; gap: 10px;
}
.timer-cell {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 12px 16px;
  min-width: 64px;
  text-align: center;
}
.timer-cell .v {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  color: var(--accent);
  display: block;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.timer-cell .l {
  font-size: 10px;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 2px;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 24px;
}
.story {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  display: flex;
  flex-direction: column;
  transition: transform 0.25s;
}
.story:hover { transform: translateY(-3px); }
.story-hero { aspect-ratio: 16/10; background-size: cover; background-position: center; position: relative; }
.story-hero::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(10,10,12,0.6) 100%);
}
.story-body { padding: 24px 26px 28px; }
.story-meta {
  display: flex; gap: 12px; align-items: center;
  font-size: 12px; color: var(--text-dim);
  text-transform: uppercase; letter-spacing: 0.08em;
  margin-bottom: 14px;
}
.story-meta .pill {
  padding: 4px 10px;
  border-radius: 100px;
  background: rgba(212,255,58,0.1);
  color: var(--accent);
  border: 1px solid rgba(212,255,58,0.2);
  letter-spacing: 0.08em;
}
.story h3 {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.story.feature h3 { font-size: 36px; }
.story p { color: var(--text-muted); font-size: 14px; }
.story-author {
  margin-top: 18px;
  display: flex; align-items: center; gap: 10px;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}
.author-ava {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--grad-accent);
  display: grid; place-items: center;
  color: var(--accent-ink);
  font-weight: 700;
  font-size: 13px;
}
.author-name { font-size: 13px; font-weight: 600; }
.author-role { font-size: 11px; color: var(--text-dim); }

.editorial-side {
  display: flex; flex-direction: column; gap: 20px;
}
.story.compact {
  flex-direction: row;
  align-items: stretch;
  min-height: 160px;
}
.story.compact .story-hero { aspect-ratio: unset; width: 200px; flex-shrink: 0; }
.story.compact .story-body { padding: 20px; }
.story.compact h3 { font-size: 18px; margin-bottom: 8px; }
.story.compact p { font-size: 13px; }

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--grad-1);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 64px 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.newsletter::before {
  content: '';
  position: absolute;
  top: -100px; right: -100px;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(212,255,58,0.1) 0%, transparent 60%);
}
.newsletter h2 {
  font-family: var(--font-display);
  font-size: 42px;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.newsletter h2 em { font-style: italic; color: var(--text-muted); font-weight: 300; }
.newsletter p { color: var(--text-muted); margin-top: 14px; }
.newsletter-form {
  position: relative;
  z-index: 2;
}
.input-row {
  display: flex;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 100px;
  padding: 6px;
  transition: border-color 0.2s;
}
.input-row:focus-within { border-color: var(--accent); }
.input-row input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  padding: 10px 18px;
  font-size: 14px;
  font-family: inherit;
}
.input-row input::placeholder { color: var(--text-dim); }
.input-row button {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  padding: 10px 22px;
  border-radius: 100px;
  font-size: 14px;
  transition: background 0.2s;
}
.input-row button:hover { background: var(--accent-hover); }
.newsletter-perks {
  display: flex; gap: 24px; margin-top: 20px;
  font-size: 12.5px; color: var(--text-muted);
}
.newsletter-perks span { display: inline-flex; align-items: center; gap: 6px; }
.newsletter-perks .check { color: var(--accent); }

/* ---------- Footer ---------- */
.footer {
  margin-top: 80px;
  padding: 64px 0 32px;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}
.footer-brand p {
  color: var(--text-muted);
  font-size: 14px;
  margin: 16px 0 24px;
  max-width: 320px;
}
.socials { display: flex; gap: 8px; }
.social {
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  display: grid; place-items: center;
  color: var(--text-muted);
  transition: all 0.2s;
}
.social:hover { color: var(--accent); border-color: var(--accent); }
.footer-col h5 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  margin-bottom: 16px;
  font-weight: 600;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col a {
  font-size: 14px;
  color: var(--text-muted);
  transition: color 0.2s;
}
.footer-col a:hover { color: var(--text); }
.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  font-size: 12.5px;
  color: var(--text-dim);
  flex-wrap: wrap;
  gap: 16px;
}
.payments { display: flex; gap: 8px; }
.pay-chip {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
}

/* ---------- Toast ---------- */
.toast-wrap {
  position: fixed;
  bottom: 24px; right: 24px;
  z-index: 100;
  display: flex; flex-direction: column; gap: 10px;
}
.toast {
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  border-left: 3px solid var(--accent);
  padding: 14px 18px;
