const Countdown = () => {
  const target = useMemo(() => Date.now() + (2 * 24 + 7) * 3600 * 1000 + 42 * 60 * 1000, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const hr = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, '0');
  const cells = [['Days', pad(d)], ['Hrs', pad(hr)], ['Min', pad(m)], ['Sec', pad(s)]];
  return h('div', { className: 'countdown' },
    h('div', { className: 'countdown-text' },
      h('h4', null, 'Member preview ends soon'),
      h('p', null, 'Early access to the autumn capsule for signed-in members.')
    ),
    h('div', { className: 'countdown-timer' },
      cells.map(([lbl, val]) =>
        h('div', { key: lbl, className: 'timer-cell' },
          h('span', { className: 'v' }, val),
          h('span', { className: 'l' }, lbl)
        )
      )
    )
  );
};

