/* ---------- App ---------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [favs, setFavs] = useState(new Set());
  const [toasts, setToasts] = useState([]);

  const pushToast = (msg) => {
    const id = Math.random().toString(36).slice(2);
    setToasts(t => [...t, { id, msg }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 2600);
  };

  const handleAdd = (p) => {
    setCart(c => [...c, p.id]);
    pushToast(`Added — ${p.title}`);
  };
  const handleFav = (id) => {
    setFavs(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  const handleSubscribe = (email) => {
    pushToast(`Subscribed — welcome aboard`);
  };
  const scrollToFeatured = () => {
    document.querySelector('.products')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  return h(Fragment, null,
    h(Announcement, null),
    h(Header, { cartCount: cart.length, favCount: favs.size }),
    h(Hero, { onShop: scrollToFeatured }),
    h(Categories, null),
    h(Featured, { onAdd: handleAdd, favs, onFav: handleFav }),
    h(Deals, null),
    h(Editorial, null),
    h(Newsletter, { onSubscribe: handleSubscribe }),
    h(Footer, null),
    h(Toasts, { items: toasts })
  );
};

ReactDOM.createRoot(document.getElementById('root')).render(h(App));
